module ByteReverse32(input [31:0] in, output [31:0] out);
  wire [7:0]  t0, t1, t2, t3, t4, t5, t6, t7, t8, t9, t10, t11, t12, t13, t14, t15, t16, t17, t18, t19, t20, t21, t22, t23, t24, t25, t26, t27, t28, t29, t30, t31;
  assign t0 = in[7:0];
  assign t1 = in[15:8];
  assign t2 = in[23:16];
  assign t3 = in[31:24];
  assign t4 = t0 << 24;
  assign t5 = t1 << 16;
  assign t6 = t2 << 8;
  assign t7 = t3;
  assign t8 = t4 | t5;
  assign t9 = t6 | t7;
  assign t10 = t8 | t9;
  assign t11 = in[15:0];
  assign t12 = t10;
  assign t13 = t11 << 16;
  assign t14 = t12 << 8;
  assign t15 = t13;
  assign t16 = t14 | t15;
  assign t17 = in[23:8];
  assign t18 = t16;
  assign t19 = t17 << 8;
  assign t20 = t18;
  assign t21 = t19 | t20;
  assign t22 = in[31:24];
  assign t23 = t21;
  assign t24 = t22 << 24;
  assign t25 = t23;
  assign t26 = t24 | t25;
  assign out = t26;
endmodule

