    // Register the input: reg_in.
    always @(posedge clk) reg_in_next <= in;
    always @(posedge clk) reg_in <= reg_in_next;
    // Chain registers together: reg0, reg1, ..., reg7.
    always @(posedge clk) reg0 <= reg_in;
    always @(posedge clk) reg1 <= reg0;
