    always @(posedge clk) reg5 <= reg4;
    always @(posedge clk) reg6 <= reg5;
    always @(posedge clk) reg7 <= reg6;
    // Detect a positive clock-to-clock transition in the register
    // chain output: pedge_reg.
    always @(posedge clk) pedge_reg_next <= {reg0 & ~reg1, reg1 & ~reg2, reg2 & ~reg3, reg3 & ~reg4, reg4 & ~reg5, reg5 & ~reg6, reg6 & ~reg7, reg7 & ~reg0};
