    input  [7:0] b,
    input  [7:0] c,
    input  [7:0] d,
    output [7:0] min
);
    // First level: compare a and b
    reg [7:0] a_b;
    always @* begin
        a_b = a < b ? a : b;
    end
    // Second level: compare a_b and c
    reg [7:0] a_b_c;
    always @* begin
        a_b_c = a_b < c ? a_b : c;
    end
    // Third level: compare a_b_c and d
    always @* begin
        min = a_b_c < d ? a_b_c : d;
    end
endmodule

module TopModule(
    input  [7:0] a,
    input  [7:0] b,
    input  [7:0] c,
    input  [7:0] d,
    output [7:0] min
);
    wire [7:0] a_lt_b = a < b;
    wire [7:0] a_lt_c = a < c;
    wire [7:0] a_lt_d = a < d;
    wire [7:0] b_lt_c = b < c;
    wire [7:0] b_lt_d = b < d;
    wire [7:0] c_lt_d = c < d;
    wire [7:0] and0 = ~a_lt_b & ~a_lt_c & ~a_lt_d;
    wire [7:0] and1 = ~b_lt_c & ~b_lt_d & and0;
    wire [7:0] and2 = ~c_lt_d & and1;
    assign min = and2 ? c : and1 ? b : and0 ? a : d;
endmodule

module TopModule(
    input  [7:0] a,
    input  [7:0] b,
    input  [7:0] c,
    input  [7:0] d,
    output [7:0] min
);
    reg [7:0] tmp0;
    reg [7:0] tmp1;
    always @(*) begin
        tmp0 = (a < b) ? a : b;
        tmp1 = (c < d) ? c : d;
        min = (tmp0 < tmp1) ? tmp0 : tmp1;
    end
endmodule

module TopModule(
    input [7:0] a, b, c, d,
    output reg [7:0] min
);
    always @(*) min = (a < b) ? ((a < c) ? ((a < d) ? a : d) : ((c < d) ? c : d)) : ((b < c) ? ((b < d) ? b : d) : ((c < d) ? c : d));
endmodule

module TopModule(
    input [7:0] a,
    input [7:0] b,
    input [7:0] c,
    input [7:0] d,
    output [7:0] min
);
    reg [7:0] tmp0, tmp1, tmp2, tmp3, tmp4, tmp5, tmp6;
    always @* begin
        tmp0 = a < b ? a : b;
        tmp1 = c < d ? c : d;
        tmp2 = tmp0 < tmp1 ? tmp0 : tmp1;
        tmp3 = a < c ? a : c;
        tmp4 = b < d ? b : d;
        tmp5 = tmp3 < tmp4 ? tmp3 : tmp4;
        tmp6 = tmp2 < tmp5 ? tmp2 : tmp5;
        min = tmp6;
    end
endmodule

