module KarnaughFunction(input a, b, output f);
    wire w1, w2, w3, w4, w5, w6, w7;
    assign w1 = a & b;
    assign w2 = ~a & b;
    assign w3 = ~a & ~b;
    assign w4 = a & ~b;
    assign w5 = ~(w1 | w2 | w3 | w4);
    assign w6 = ~(w1 & w2 & w3 & w4);
    assign w7 = ~(w1 ^ w2 ^ w3 ^ w4);
    assign f = w5 | w6 | w7;
endmodule

