module TopModule(
  input  clk,
  input  a,
  input  b,
  output out_assign,
  output out_always_comb,
  output out_always_ff
);
  assign out_assign = a ^ b;
  always @(*) out_always_comb = a ^ b;
  reg out_ff;
  always @(posedge clk) out_ff <= a ^ b;
  assign out_always_ff = out_ff;
endmodule

// One-bit XOR, implemented with an assign statement. This is an inline
// multiplexer, so the Fmax is higher.
assign out_assign = a ^ b;

// One-bit XOR, implemented with a combinational always block. This is a
// tree of AND / OR gates, so the Fmax is lower.
always @(*) begin
    out_always_comb = a ^ b;
end

// One-bit XOR, implemented with a clocked always block. This is a short
// path pipeline, so higher Fmax than the other two.
reg [1:0] stage0, stage1, stage2;
always @(posedge clk) stage0 <= {a, b};
always @(posedge clk) stage1 <= stage0;
always @(posedge clk) stage2 <= stage1;
always @(posedge clk) out_always_ff <= stage2[0] ^ stage2[1];

// The combined function of all three XOR gates, used to ensure that the
// separate functions give the same result.
wire combined = out_assign & out_always_comb & out_always_ff;

// A short path pipeline to AND the combined function with the clock, to
// make the long Fmax path pipeline (out_always_ff) the same long path as
// the other two Fmax paths (out_assign, out_always_comb). This changes
// the critical path from the register stage to the AND stage, which
// increases Fmax.
reg [1:0] stage3, stage4;
always @(posedge clk) stage3 <= {combined, 1'b1};
always @(posedge clk) stage4 <= stage3;
wire combined_pipelined = stage4[0];

// A one-bit register, used to make the long Fmax path pipeline (the
// out_always_ff register) the same long path as the other two Fmax paths
// (the assign and always @ (*) functions).
reg [1:0] stage5;
always @(posedge clk) stage5 <= {1'b1, 1'b1};
wire one_register = stage5[0];

// The final combined function, which is a short path pipeline ANDed with
// a one-bit register (to make the long Fmax path pipeline the same long
// path as the other two Fmax paths), gives the same function as the
// separate functions (out_assign, out_always_comb, out_always_ff) when
// the inputs are independent and the clock frequency is high enough.
assign combined_function = combined_pipelined & one_register;
endmodule

