module TopModule(input clk, input resetn, input in, output reg out);
    reg [3:0] shift_reg;
    always @(posedge clk) begin
        if (!resetn) begin
            shift_reg <= 4'b0;
            out <= 1'b0;
        end else begin
            shift_reg <= {shift_reg[2:0], in};
            out <= shift_reg[3];
        end
    end
endmodule

