  wire [2:0] ena_inc_ones, ena_inc_tens, ena_inc_hundreds, ena_inc_thousands;
  assign ones = count[3:0];
  assign tens = count[7:4];
  assign hundreds = count[11:8];
  assign thousands = count[15:12];
  assign ena_inc_ones = (ones == 4) ? 3'b111 : 3'b110;
  assign ena_inc_tens = (tens == 4) ? ena_inc_ones : 3'b101;
  assign ena_inc_hundreds = (hundreds == 4) ? ena_inc_tens : 3'b100;
  assign ena_inc_thousands = (thousands == 4) ? ena_inc_hundreds : 3'b011;
  assign ena = ena_inc_thousands;
  always @(posedge clk) begin
    if (reset) begin
      count <= 16'd0;
    end else begin
      count <= count + 16'd1;
    end
  end
  always @(posedge clk) begin
    if (reset) begin
      count <= 16'd0;
    end else if (ena_inc_ones == 3'b111) begin
      count[3:0] <= 4'd0;
