// One-bit synchronous register. The register is triggered by the clock on the
// first clock cycle of the register, and the data on the second clock cycle.
// This forms a sequential "memory" of the inputs.
reg mode_r, too_cold_r, too_hot_r, fan_on_r;
always @(posedge clk) begin
    mode_r <= mode;
    too_cold_r <= too_cold;
    too_hot_r <= too_hot;
    fan_on_r <= fan_on;
end

// The actual thermostat controller logic, implemented in a single line of
// combinational Verilog. This is the functional model of the thermostat
// described in the problem description.
assign {heater, aircon, fan} = {2'b000, mode_r & too_cold_r, mode_r & too_hot_r} | {2'b010, ~mode_r & too_cold_r} | {2'b100, ~mode_r & too_hot_r} | {2'b011, fan_on_r};
endmodule

