module ThermostatFSM(mode, too_cold, too_hot, fan_on, heater, aircon, fan);
  input mode;
  input too_cold;
  input too_hot;
  input fan_on;
  output heater;
  output aircon;
  output fan;
  reg [2:0] state;
  always @(*) begin
    case(state)
      3'd0: begin // Idle, fan off. Turn on heater if too cold.
        heater = ~too_cold;
        aircon = 1'b0;
        fan = 1'b0;
        if(too_cold) state = 3'd1;
      end
      3'd1: begin // Heating, fan off. Turn on fan if requested.
        heater = 1'b1;
        aircon = 1'b0;
        fan = fan_on;
        if(fan_on) state = 3'd2;
      end
      3'd2: begin // Heating, fan on.
        heater = 1'b1;
        aircon = 1'b0;
        fan = 1'b1;
        if(~too_cold & ~fan_on) state = 3'd0;
        if(too_cold & ~fan_on) state = 3'd1;
      end
      3'd3: begin // Cooling, fan off. Turn on aircon if too hot.
        heater = 1'b0;
        aircon = ~too_hot;
        fan = 1'b0;
        if(too_hot) state = 3'd4;
      end
      3'd4: begin // Cooling, fan off. Turn on fan if requested.
        heater = 1'b0;
        aircon = 1'b1;
        fan = fan_on;
        if(fan_on) state = 3'd5;
      end
      3'd5: begin // Cooling, fan on.
        heater = 1'b0;
        aircon = 1'b1;
        fan = 1'b1;
        if(~too_hot & ~fan_on) state = 3'd3;
        if(too_hot & ~fan_on) state = 3'd4;
      end
      default: begin // Should never happen.
        heater = 1'b0;
        aircon = 1'b0;
        fan = 1'b0;
        state = 3'd0;
      end
    endcase
  end
  always @(*) begin
    if(mode) state = 3'd3;
    else state = 3'd0;
  end
endmodule

