module TopModule(input clk, input x, output z);
    reg [2:0] state;
    reg [2:0] next_state;
    reg [2:0] d0, d1, d2;
    wire [2:0] ff0, ff1, ff2;
    wire [2:0] nand0, nand1, nand2;
    wire [2:0] xor0, and0, or0;
    wire [2:0] nor0;

    // D flip-flops with initial reset to 0
    always @(posedge clk) begin
        d0 <= 3'b0;
        d1 <= 3'b0;
        d2 <= 3'b0;
        state <= next_state;
    end
    always @(posedge clk) begin
        if (state == 3'b000) begin
            d0 <= 3'b001;
            next_state <= 3'b001;
        end else if (state == 3'b001) begin
            d0 <= 3'b010;
            next_state <= 3'b010;
        end else if (state == 3'b010) begin
            d0 <= 3'b100;
            next_state <= 3'b100;
        end else if (state == 3'b100) begin
            d0 <= 3'b000;
            next_state <= 3'b000;
        end
    end
    always @(posedge clk) begin
        if (state == 3'b000) begin
            d1 <= 3'b000;
            next_state <= 3'b000;
        end else if (state == 3'b001) begin
            d1 <= 3'b100;
            next_state <= 3'b100;
        end else if (state == 3'b010) begin
            d1 <= 3'b010;
            next_state <= 3'b010;
        end else if (state == 3'b100) begin
            d1 <= 3'b001;
            next_state <= 3'b001;
        end
    end
    always @(posedge clk) begin
        if (state == 3'b000) begin
            d2 <= 3'b000;
            next_state <= 3'b000;
        end else if (state == 3'b001) begin
            d2 <= 3'b001;
            next_state <= 3'b001;
        end else if (state == 3'b010) begin
            d2 <= 3'b011;
            next_state <= 3'b011;
        end else if (state == 3'b100) begin
            d2 <= 3'b111;
            next_state <= 3'b111;
        end
    end

    // Two-input gates, one per FF, in parallel
    assign ff0 = ~d0 & x;
    assign ff1 = ~d1 & x;
    assign ff2 = ~d2 & x;
    assign nand0 = ~(ff0 & ff1);
    assign nand1 = ~(ff0 & ff2);
    assign nand2 = ~(ff1 & ff2);
    assign xor0 = ff0 ^ ff1;
    assign and0 = ff0 & (~ff1);
    assign or0 = ff0 | (~ff1);

    // Three-input NOR gate
    assign nor0 = ~(nand0 | nand1 | nand2);

    // Output the NOR gate
    assign z = nor0;
endmodule

