module TopModule (
    input  clk,
    input  x,
    output z
);
    reg [2:0] state;
    wire [2:0] next_state;
    wire xor0, xor1, xor2, and0, and1, and2, or0, or1, or2;
    wire [2:0] nand0;
    DFF_X0 d0 (.Q(xor0), .D(x), .CLK(clk));
    DFF_X0 d1 (.Q(and0), .D(~xor0), .CLK(clk));
    DFF_X0 d2 (.Q(or0), .D(~and0), .CLK(clk));
    DFF_X0 d3 (.Q(xor1), .D(x), .CLK(clk));
    DFF_X0 d4 (.Q(and1), .D(~xor1), .CLK(clk));
    DFF_X0 d5 (.Q(or1), .D(~and1), .CLK(clk));
    DFF_X0 d6 (.Q(xor2), .D(x), .CLK(clk));
    DFF_X0 d7 (.Q(and2), .D(~xor2), .CLK(clk));
    DFF_X0 d8 (.Q(or2), .D(~and2), .CLK(clk));
    NOR3_X0 n0 (.O(nand0), .I0(xor0), .I1(and0), .I2(or0));
    NOR3_X0 n1 (.O(nand1), .I0(xor1), .I1(and1), .I2(or1));
    NOR3_X0 n2 (.O(nand2), .I0(xor2), .I1(and2), .I2(or2));
    always @* begin
        case (state)
            3'b000: next_state = 3'b001;
            3'b001: next_state = 3'b010;
            3'b010: next_state = 3'b011;
            3'b011: next_state = 3'b100;
            3'b100: next_state = 3'b101;
            3'b101: next_state = 3'b110;
            3'b110: next_state = 3'b111;
            3'b111: next_state = 3'b000;
        endcase
    end
    always @(posedge clk) begin
        state <= next_state;
    end
    assign z = ~nand0;
endmodule

