  input  [3:0] data3,
  input  [3:0] data4,
  input  [3:0] data5,
  output [3:0] out
);
  // One-hot select -> multiply-add chain -> one register FF (shortest
  // path to FF -> lowest delay).
  wire [15:0] product0 = sel[0] ? 4'd1 : 4'd0;
  wire [15:0] product1 = sel[0] ? 4'd0 : 4'd1;
  wire [15:0] product2 = sel[0] ? 4'd2 : 4'd0;
  wire [15:0] product3 = sel[0] ? 4'd0 : 4'd2;
  wire [15:0] product4 = sel[0] ? 4'd3 : 4'd0;
  wire [15:0] product5 = sel[0] ? 4'd0 : 4'd3;
  wire [15:0] product6 = sel[0] ? 4'd4 : 4'd0;
  wire [15:0] product7 = sel[0] ? 4'd0 : 4'd4;
  wire [15:0] product8 = sel[0] ? 4'd5 : 4'd0;
  wire [15:0] product9 = sel[0] ? 4'd0 : 4'd5;
  wire [15:0] sum0 = product0 + product1 + product2 + product3 + product4 + product5 + product6 + product7 + product8 + product9;
  reg  [3:0] latched_out;
  always @(posedge sel[1] or posedge sel[2]) begin
    latched_out <= sum0[3:0];
  end
  assign out = latched_out;
endmodule

