module TopModule(input in, input [3:0] state, output [3:0] next_state, output out);
    // One-hot encoded state names: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000
    // Derived transition logic: one multiplexed output for each input
    // (in=0, in=1) pair, followed by a combinational logic function that goes
    // from one state to the next (as specified in the state transition table).
    // Derived output logic: a simple combinational function that goes from
    // one state to the corresponding output (as specified in the state transition
    // table).
    reg [3:0] next_state_comb;
    always @* begin
        case ({in, state})
            4'b0000: next_state_comb = 4'b0001;
            4'b0001: next_state_comb = 4'b0010;
            4'b0010: next_state_comb = 4'b0100;
            4'b0011: next_state_comb = 4'b0010;
            4'b0100: next_state_comb = 4'b1000;
            4'b0101: next_state_comb = 4'b0100;
            4'b0110: next_state_comb = 4'b0001;
            4'b0111: next_state_comb = 4'b1000;
            4'b1000: next_state_comb = 4'b0001;
            4'b1001: next_state_comb = 4'b0100;
            4'b1010: next_state_comb = 4'b0010;
            4'b1011: next_state_comb = 4'b0010;
            4'b1100: next_state_comb = 4'b0001;
            4'b1101: next_state_comb = 4'b0001;
            4'b1110: next_state_comb = 4'b1000;
            4'b1111: next_state_comb = 4'b1000;
        endcase
    end
    assign next_state = next_state_comb;
    assign out = (next_state == 4'b0001) ? 1'b0 : 1'b1;
endmodule

module TopModule(input in, input [3:0] state, output [3:0] next_state,
                 output reg out);
  always @(*) begin
    out = 1'b0;
    next_state = 4'b0000;
    case (state)
      4'b0001: begin
        next_state = in ? 4'b0100 : 4'b0001;
      end
      4'b0010: begin
        next_state = in ? 4'b0010 : 4'b0010;
      end
      4'b0100: begin
        next_state = in ? 4'b1000 : 4'b0001;
        out = 1'b1;
      end
      4'b1000: begin
        next_state = in ? 4'b0010 : 4'b0010;
      end
    endcase
  end
endmodule

module TopModule(
    input in,
    input [3:0] state,
    output [3:0] next_state,
    output out
);
    reg [3:0] next_state_reg;
    reg out_reg;
    always @(*) begin
        case (state)
            4'b0001: begin
                next_state_reg = 4'b0001;
                out_reg = 1'b0;
            end
            4'b0010: begin
                if (in) begin
                    next_state_reg = 4'b0010;
                    out_reg = 1'b0;
                end else begin
                    next_state_reg = 4'b0100;
                    out_reg = 1'b0;
                end
            end
            4'b0100: begin
