            end
            4'b1000: begin
                if (in) begin
                    next_state_reg = 4'b0001;
                    out_reg = 1'b1;
                end else begin
                    next_state_reg = 4'b0100;
                    out_reg = 1'b0;
                end
            end
            default: begin
                next_state_reg = 4'b0001;
                out_reg = 1'b0;
