        endcase
    end
    assign next_state = next_state_reg;
    assign out = out_reg;
endmodule

module TopModule(
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output out
);
    // State transition logic (combinational, derived from the table):
    always @(*) begin
        case (state)
            4'b0001: next_state = in ? 4'b0010 : 4'b0001;
            4'b0010: next_state = in ? 4'b0100 : 4'b0010;
            4'b0100: next_state = in ? 4'b1000 : 4'b0100;
            4'b1000: next_state = in ? 4'b0001 : 4'b1000;
            default: next_state = 4'b0001;
        endcase
    end
    // Output logic (combinational, derived from the table):
    always @(*) begin
        case (state)
            4'b0001: out = 1'b0;
            4'b0010: out = 1'b0;
            4'b0100: out = 1'b0;
            4'b1000: out = 1'b1;
            default: out = 1'b0;
