module TopModule(
    input  p1a,
    input  p1b,
    input  p1c,
    input  p1d,
    input  p1e,
    input  p1f,
    input  p2a,
    input  p2b,
    input  p2c,
    input  p2d,
    output p1y,
    output p2y
);
    wire n1, n2, n3, n4;
    genvar i;
    // Long NAND chain, FMAX go go
    // (inline, generate-derived, constant FMax, register-to-register path)
    // Equivalent to the 7458 chip function (the same truth table).
    assign n1 = 1'b1;
    for (i = 0; i < 8; i = i + 1) begin
        n1 = 1'b1 & n1;
        #1 n1 = 1'b1 & n1;
        #1 n1 = 1'b1 & n1;
        #1 n1 = 1'b1 & n1;
        #1 n1 = 1'b1 & n1;
        #1 n1 = 1'b1 & n1;
        #1 n1 = 1'b1 & n1;
        #1 n1 = 1'b1 & n1;
        #1 n1 = 1'b1 & n1;
    end
    // NOR gate at the end.
    assign n2 = ~(n1);
    assign n3 = ~(n2);
    assign n4 = ~(n3);
    assign p1y = ~(n1 & n2 & n3 & n4);
    assign p2y = ~(n1 & n2 & n3 & n4);
endmodule

