  reg [2:0] byte_count;
  reg [7:0] bytes [2:0];
  reg done_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      byte_count <= 3'b000;
      bytes <= '{8'h0, 8'h0, 8'h0};
      done_reg <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // Wait for first byte with in[3]=1
          if (in[3]) begin
            state <= 2'b01;
            byte_count <= 3'b001;
            bytes[0] <= in;
          end
        end
        2'b01: begin // Wait for second byte
          byte_count <= byte_count + 1;
          bytes[1] <= in;
          if (byte_count == 3'b100) begin
            state <= 2'b10;
            byte_count <= 3'b000;
          end
        end
        2'b10: begin // Wait for third byte
          byte_count <= byte_count + 1;
          bytes[2] <= in;
          if (byte_count == 3'b100) begin
            state <= 2'b00;
            byte_count <= 3'b000;
            done_reg <= 1'b1;
          end
        end
      endcase
    end
  end

  assign done = done_reg;
endmodule

