            state <= 3'b000;
            byte_idx <= 3'b000;
            done_reg <= 1'b0;
        end else begin
            case (state)
                3'b000: begin // Wait for first byte with in[3]=1
                    if (in[3]) begin
                        bytes[0] <= in;
                        byte_idx <= 3'b001;
                        state <= 3'b001;
                    end
                end
                3'b001: begin // Receive second byte
                    bytes[1] <= in;
                    byte_idx <= 3'b010;
                    state <= 3'b010;
                end
                3'b010: begin // Receive third byte, end message
                    bytes[2] <= in;
                    byte_idx <= 3'b011;
                    state <= 3'b011;
                    done_reg <= 1'b1;
                end
                3'b011: begin // Wait for a new message (reset FSM)
                    if (!in[3]) begin
                        state <= 3'b000;
                        done_reg <= 1'b0;
                    end
                end
            endcase
        end
    end

    assign done = done_reg;
