module TopModule(input clk, input reset, input in, output done);
  // FSM states
  parameter IDLE = 2'b00;
  parameter D0 = 2'b01;
  parameter D1 = 2'b10;
  parameter D2 = 2'b11;
  parameter D3 = 2'b00;
  parameter D4 = 2'b01;
  parameter D5 = 2'b10;
  parameter D6 = 2'b11;
  parameter D7 = 2'b00;
  parameter STOP = 2'b01;
  reg [1:0] state, next_state;
  // Internal registers
  reg [7:0] byte;
  reg [2:0] bit_count;
  // Output register
  reg done_reg;
  // Combinational logic for the next state and register updates
  always @(*) begin
    next_state = state;
    done_reg = 1'b0;
    case (state)
      IDLE: if (in == 1'b0) next_state = D0;
      D0: begin
        next_state = D1;
        byte = {in, byte[7:1]};
      end
      D1: begin
        next_state = D2;
        byte = {in, byte[7:1]};
      end
      D2: begin
        next_state = D3;
        byte = {in, byte[7:1]};
      end
      D3: begin
        next_state = D4;
        byte = {in, byte[7:1]};
      end
      D4: begin
        next_state = D5;
        byte = {in, byte[7:1]};
      end
      D5: begin
        next_state = D6;
        byte = {in, byte[7:1]};
      end
      D6: begin
        next_state = D7;
        byte = {in, byte[7:1]};
      end
      D7: begin
        next_state = STOP;
        byte = {in, byte[7:1]};
      end
      STOP: begin
        next_state = IDLE;
        done_reg = (in == 1'b1);
      end
    endcase
  end
  // Sequential logic for the registers
  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      byte <= 8'b0;
      bit_count <= 3'b0;
    end else begin
      state <= next_state;
      if (state == IDLE) begin
        byte <= 8'b0;
        bit_count <= 3'b0;
      end else if (state == STOP) begin
        bit_count <= bit_count + 1;
      end
    end
  end
  // Output register
  assign done = done_reg;
endmodule

module TopModule(input clk, input reset, input in, output reg done);
    reg [2:0] state;
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            done <= 1'd0;
        end
        else begin
            case (state)
                3'd0: begin // idle -> wait for start bit
                    if (in) state <= 3'd1;
                end
                3'd1: begin // wait for start bit -> wait for data bits
                    state <= 3'd2;
                end
                3'd2: begin // wait for data bits -> wait for data bits
                    state <= 3'd3;
                end
                3'd3: begin // wait for data bits -> wait for data bits
                    state <= 3'd4;
                end
                3'd4: begin // wait for data bits -> wait for data bits
                    state <= 3'd5;
                end
                3'd5: begin // wait for data bits -> wait for data bits
                    state <= 3'd6;
                end
                3'd6: begin // wait for data bits -> wait for data bits
                    state <= 3'd7;
                end
                3'd7: begin // wait for data bits -> wait for data bits
                    state <= 3'd8;
                end
                3'd8: begin // wait for data bits -> wait for stop bit
                    state <= 3'd9;
                end
                3'd9: begin // wait for stop bit -> wait for start bit
                    if (in) state <= 3'd1;
                    else state <= 3'd0;
                    done <= 1'd1;
                end
            endcase
        end
    end
    always @(*) begin
        case (state)
            3'd0: done <= 1'd0;
            3'd9: done <= 1'd1;
            default: done <= 1'd0;
        endcase
    end
endmodule

module TopModule(input clk, input reset, input in, output reg done);
  reg [2:0] state;
  reg [7:0] data;
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      data <= 8'b0;
      done <= 1'b0;
    end else begin
      case (state)
        3'b000: begin // idle
          if (in == 1'b0) begin
            state <= 3'b001;
          end
        end
        3'b001: begin // start bit seen, wait for data bits
          data <= {in, data[7:1]};
          state <= 3'b010;
        end
        3'b010: begin // data bits 0-6
          data <= {in, data[7:1]};
          if (&state) begin
            state <= 3'b011;
          end else begin
            state <= state + 1;
          end
        end
        3'b011: begin // data bit 7
          data <= {in, data[7:1]};
          if (in) begin
            state <= 3'b100;
          end else begin
            state <= 3'b000;
          end
        end
        3'b100: begin // error, back to idle
          state <= 3'b000;
        end
      endcase
      done <= (state == 3'b001) & (in == 1'b0);
    end
  end
endmodule

module TopModule(
