module TopModule(
    input  clk,
    input  reset,
    input  w,
    output z
);
    // State codes
    parameter [2:0] A = 3'b000, B = 3'b001, C = 3'b010, D = 3'b011,
                    E = 3'b100, F = 3'b101;
    reg [2:0] state, next_state;

    // State table
    always @ (*) begin
        case (state)
            A: if (w) next_state = B; else next_state = A;
            B: if (w) next_state = C; else next_state = D;
            C: if (w) next_state = E; else next_state = D;
            D: if (w) next_state = F; else next_state = A;
            E: if (w) next_state = E; else next_state = D;
            F: if (w) next_state = C; else next_state = D;
            default: next_state = A;
        endcase
    end

    // State flip-flops
    always @ (posedge clk) begin
        if (reset) state <= A;
        else state <= next_state;
    end

    // FSM output
    assign z = (state == F);
endmodule

module TopModule(
    input clk,
    input resetn,
    input x,
    input y,
    output reg f,
    output reg g
);
    // The state variable is a one-hot encoded bit vector. The names of the
    // states are the Verilog symbolic names for the bit positions. This means
    // that the state can be inferred as a one-hot encoded register, which is
    // inline with the standard for synchronous FSMs.
    reg [2:0] state;
    always @(posedge clk) begin
        if (!resetn) begin
            state <= 3'b001;
            f <= 1;
            g <= 0;
        end else begin
            case (state)
                3'b001: begin
                    f <= 1;
                    g <= 0;
                    if (x && !y) state <= 3'b010;
                end
                3'b010: begin
                    f <= 1;
                    g <= 0;
                    if (x && !y) state <= 3'b011;
                    else if (x && y) state <= 3'b100;
                end
                3'b011: begin
                    f <= 1;
                    g <= 0;
                    if (x && !y) state <= 3'b100;
                end
                3'b100: begin
                    f <= 0;
                    g <= 1;
                    if (!y) state <= 3'b101;
                end
                3'b101: begin
                    f <= 0;
                    g <= 1;
                    if (y) state <= 3'b110;
                end
                3'b110: begin
                    f <= 0;
                    g <= 1;
                    if (!x) state <= 3'b001;
                end
            endcase
        end
    end
endmodule

module FSM(
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output reg f,
    output reg g
);
    reg [1:0] state;
    always @(posedge clk) begin
        if (!resetn) begin
            state <= 2'b00;
            f <= 1'b1;
            g <= 1'b0;
        end else begin
            case (state)
                2'b00: begin // A
                    f <= 1'b1;
                    g <= 1'b0;
                    if (x == 1 && x == $past(x) && x == $past(x) && y == 1 && y == $past(y) && y == $past(y)) state <= 2'b01;
                end
                2'b01: begin // B
                    f <= 1'b0;
                    g <= 1'b1;
                    if (y != 1) state <= 2'b10;
                end
                2'b10: begin // C
                    f <= 1'b0;
                    g <= 1'b0;
                    if (y == 1 && y == $past(y) && y == $past(y)) state <= 2'b01;
                end
            endcase
        end
    end
endmodule

module TopModule(
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output reg f,
    output reg g
);
    // Declare the states of the FSM as an enumerated type.
    parameter S_A = 2'd0, S_B = 2'd1, S_C = 2'd2, S_D = 2'd3;
    reg [1:0] state, next_state;

    // Register the inputs on the clock to get a clocked version of them,
    // named $x and $y.
    reg $x, $y;
    always @(posedge clk) begin
        $x <= x;
        $y <= y;
    end

    // The combinatorial block that defines the next state and outputs.
    always @(*) begin
        case (state)
            S_A: begin
                next_state = resetn ? S_B : S_A;
                f = 1;
                g = 0;
            end
            S_B: begin
                next_state = $x ? S_C : S_B;
                f = 0;
                g = 0;
            end
            S_C: begin
                next_state = $x && $x && $x ? S_D : S_C;
                f = 0;
                g = 0;
            end
            S_D: begin
                next_state = $y ? S_D : S_A;
                f = 0;
                g = 1;
            end
        endcase
    end

    // Synchronous register to hold the state.
    always @(posedge clk) begin
        state <= next_state;
    end
endmodule

module TopModule(input clk, input resetn, input x, input y, output reg f, output reg g);
  reg [1:0] state;
  reg [1:0] x_delay;
  reg [1:0] y_delay;
  always @(posedge clk) begin
    if (!resetn) begin
      state <= 2'b00;
      f <= 1'b0;
      g <= 1'b0;
      x_delay <= 2'b00;
      y_delay <= 2'b00;
    end else begin
      case (state)
        2'b00: begin // Beginning state.
          f <= 1'b1;
          g <= 1'b0;
          state <= 2'b01;
        end
        2'b01: begin // Wait for x = 1, 0, 1 in three cycles.
          f <= 1'b1;
          g <= 1'b0;
          x_delay <= {x_delay[0], x};
          if (x_delay == 2'b01010) begin
            state <= 2'b10;
          end
        end
        2'b10: begin // Wait for y = 1 within two cycles.
          f <= 1'b1;
          g <= 1'b1;
          y_delay <= {y_delay[0], y};
          if (y_delay == 2'b01) begin
            // Do nothing.
          end else begin
            g <= 1'b0;
            state <= 2'b11;
          end
        end
        2'b11: begin // Wait for y = 1 within two cycles.
          f <= 1'b1;
          g <= 1'b1;
          y_delay <= {y_delay[0], y};
          if (y_delay == 2'b01) begin
            // Do nothing.
          end else begin
            g <= 1'b0;
            state <= 2'b11;
          end
        end
      endcase
    end
  end
endmodule

module TopModule(
    input clk,
    input resetn,
    input x,
    input y,
    output reg f,
    output reg g
);
    // Declare the state register and the next state combinational
    // expression.
    reg [1:0] state, next_state;
    always @(*) begin
        case (state)
            2'b00: next_state = 2'b01; // A -> B
            2'b01: next_state = (x && x && x) ? 2'b10 : 2'b01; // B -> C
            2'b10: next_state = (y) ? 2'b10 : 2'b00; // C -> D
            2'b11: next_state = 2'b10; // D -> C
            default: next_state = 2'b00;
        endcase
    end
    // Register the state, with the reset synchronously set to the
