module TopModule(input clk, input resetn, input x, input y, output f, output g);
  // Define the states of the finite state machine.
  parameter A = 2'b00, B = 2'b01, C = 2'b10, D = 2'b11;
  reg [1:0] state, next_state;
  // Register the intermediate signals to produce sequential logic.
  reg [2:0] x_delay;
  reg [1:0] y_delay;
  always @(posedge clk) begin
    if (!resetn) begin
      state <= A;
      x_delay <= 3'b000;
      y_delay <= 2'b00;
    end else begin
      state <= next_state;
      x_delay <= {x_delay[1:0], x};
      y_delay <= {y_delay[0], y};
    end
  end
  // Define the transitions and outputs of the FSM.
  always @* begin
    case (state)
      A: begin
        f = 1;
        g = 0;
        next_state = B;
      end
      B: begin
        f = 1;
        g = 0;
        if (x_delay == 3'b00101) next_state = C;
        else next_state = B;
      end
      C: begin
        f = 1;
        g = 1;
        next_state = D;
      end
      D: begin
        f = 1;
        g = 1;
        if (y_delay <= 2'b01) next_state = D;
        else next_state = A;
      end
    endcase
  end
endmodule

module FSM(
    input clk,
    input resetn,
    input x,
    input y,
    output reg f,
    output reg g
);
    reg [1:0] state;
    reg [1:0] next_state;
    reg [1:0] x_d1;
    reg [1:0] x_d2;
    reg [1:0] y_d1;
    reg [1:0] y_d2;
    always @(posedge clk) begin
        if (!resetn) begin
            state <= 2'b00;
            f <= 1;
            g <= 0;
            x_d1 <= 1;
            x_d2 <= 1;
            y_d1 <= 1;
            y_d2 <= 1;
        end else begin
            state <= next_state;
            f <= (state == 2'b01);
            g <= (state == 2'b01) | (state == 2'b10);
            x_d1 <= x;
            x_d2 <= x_d1;
            y_d1 <= y;
            y_d2 <= y_d1;
        end
    end
    always @(*) begin
        case (state)
            2'b00: next_state = (x_d1 & ~x_d2 & x_d2) ? 2'b01 : 2'b00;
            2'b01: next_state = (~x_d1 & ~y_d2) ? 2'b00 : 2'b10;
            2'b10: next_state = (x_d1 & ~x_d2 & x_d2 & ~y_d2) ? 2'b01 : 2'b10;
            default: next_state = 2'b00;
        endcase
    end
endmodule

