module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output reg walk_left,
    output reg walk_right,
    output reg aaah
);
    reg [1:0] state;
    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b00;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
        end else begin
            case (state)
                2'b00: begin // walking left, no bump
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    if (bump_left) state <= 2'b01; // bumped left, go right
                    else if (bump_right) state <= 2'b10; // bumped right, go left
                    else if (!ground) state <= 2'b11; // fell off the ground, say aaah
                end
                2'b01: begin // walking right after bumping left, no bump
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    state <= 2'b00; // back to walking left
                end
                2'b10: begin // walking left after bumping right, no bump
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    state <= 2'b00; // back to walking left
                end
                2'b11: begin // falling off the ground, no bump
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b1;
                    if (ground) state <= 2'b00; // ground reappeared, go back to walking
                end
            endcase
        end
    end
endmodule

module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output reg walk_left,
    output reg walk_right,
    output reg aaah
);
    reg [1:0] state;
    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b00;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
        end else begin
            case (state)
                2'b00: begin // walking left
                    walk_left <= 1;
                    walk_right <= 0;
                    aaah <= 0;
                    if (bump_left) state <= 2'b01;
                    else if (ground) state <= 2'b00;
                    else state <= 2'b10;
                end
                2'b01: begin // bumped left
                    walk_left <= 0;
                    walk_right <= 1;
                    aaah <= 0;
                    if (bump_right) state <= 2'b00;
                    else if (ground) state <= 2'b01;
                    else state <= 2'b11;
                end
                2'b10: begin // falling
                    walk_left <= 1;
                    walk_right <= 0;
                    aaah <= 1;
                    if (ground) begin
                        state <= 2'b00;
                        aaah <= 0;
                    end
                end
                2'b11: begin // bumped while falling
                    walk_left <= 0;
                    walk_right <= 1;
                    aaah <= 1;
                    if (ground) begin
                        state <= 2'b01;
                        aaah <= 0;
                    end
                end
            endcase
        end
    end
endmodule

module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output reg walk_left,
    output reg walk_right,
    output reg aaah
);
    reg [1:0] state;
    always @(posedge clk) begin
        if (areset) begin
            state <= 2'd0;
            walk_left <= 1'd1;
            walk_right <= 1'd0;
            aaah <= 1'd0;
        end else begin
            case (state)
                2'd0: begin // walking left
                    walk_left <= 1'd1;
                    walk_right <= 1'd0;
                    aaah <= 1'd0;
                    if (bump_left) state <= 2'd1;
                    else if (bump_right) state <= 2'd2;
                    else if (ground == 1'd0) state <= 2'd3;
                end
                2'd1: begin // walking right
                    walk_left <= 1'd0;
                    walk_right <= 1'd1;
                    aaah <= 1'd0;
                    if (bump_left) state <= 2'd0;
                    else if (bump_right) state <= 2'd2;
                    else if (ground == 1'd0) state <= 2'd3;
                end
                2'd2: begin // bumped left or right, going the other way
                    walk_left <= 1'd0;
                    walk_right <= 1'd0;
                    aaah <= 1'd0;
                    if (bump_left) state <= 2'd1;
                    else if (bump_right) state <= 2'd0;
                    else if (ground == 1'd0) state <= 2'd3;
                end
                2'd3: begin // falling, not bumping
                    walk_left <= 1'd0;
                    walk_right <= 1'd0;
                    aaah <= 1'd1;
                    if (ground == 1'd1) state <= 2'd0;
                end
            endcase
        end
    end
endmodule

module TopModule(
  input  clk,
  input  areset,
  input  bump_left,
  input  bump_right,
  input  ground,
  output walk_left,
  output walk_right,
  output aaah
);
  reg [1:0] state /* verilator FSM_ENC "BLACKBOX" */;
  wire [1:0] next_state;
  reg walk_left_reg;
  reg walk_right_reg;
  reg aaah_reg;
  assign walk_left = walk_left_reg;
  assign walk_right = walk_right_reg;
  assign aaah = aaah_reg;
  always @(posedge clk) begin
    if (areset) begin
      state <= 2'd0;
      walk_left_reg <= 1'd1;
      walk_right_reg <= 1'd0;
      aaah_reg <= 1'd0;
    end else begin
      state <= next_state;
      walk_left_reg <= (state == 2'd0);
      walk_right_reg <= (state == 2'd1);
      aaah_reg <= (state == 2'd2);
    end
  end
  always @* begin
    case (state)
      2'd0: next_state = (bump_right ? 2'd1 : (bump_left ? 2'd1 : (ground ? 2'd0 : 2'd2)));
      2'd1: next_state = (bump_left ? 2'd0 : (bump_right ? 2'd0 : (ground ? 2'd1 : 2'd2)));
      2'd2: next_state = (bump_left ? 2'd0 : (bump_right ? 2'd1 : 2'd2));
      default: next_state = 2'd0;
    endcase
  end
endmodule

module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output reg walk_left,
    output reg walk_right,
    output reg aaah
);
    always @(posedge clk) begin
        if (areset) begin
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
        end else begin
            case ({bump_left, bump_right, ground})
                3'b000: begin // STATE_WALK_LEFT
                    walk_left <= 1;
                    walk_right <= 0;
                    aaah <= 0;
                end
                3'b001: begin // STATE_WALK_LEFT
                    walk_left <= 1;
                    walk_right <= 0;
                    aaah <= 0;
                end
                3'b010: begin // STATE_WALK_LEFT
                    walk_left <= 1;
                    walk_right <= 0;
                    aaah <= 0;
                end
                3'b011: begin // STATE_WALK_RIGHT
                    walk_left <= 0;
                    walk_right <= 1;
                    aaah <= 0;
                end
                3'b100: begin // STATE_WALK_RIGHT
                    walk_left <= 0;
                    walk_right <= 1;
                    aaah <= 0;
                end
                3'b101: begin // STATE_WALK_RIGHT
                    walk_left <= 0;
                    walk_right <= 1;
                    aaah <= 0;
                end
                3'b110: begin // STATE_FALL
                    walk_left <= 0;
                    walk_right <= 0;
                    aaah <= 1;
                end
                3'b111: begin // STATE_LAND
                    walk_left <= 1;
                    walk_right <= 0;
                    aaah <= 0;
                end
            endcase
        end
    end
endmodule

module TopModule(
    input  in,
    input  [9:0] state,
    output [9:0] next_state,
    output out1,
    output out2
    );
    // Next state function: a combinational Circut, without any flip-flops.
    // Implement the function f(state, in) from the state transition diagram.
    // This is a multiplexer chain, with one multiplexer per FUNCTIONAL
    // state (the states used in the FUNCTION, not the register states in the
    // register-transferring diagram).
    wire [9:0] func_state;
    assign func_state[0] = 1'b1;
    genvar i;
    for (i = 1; i < 10; i = i + 1) begin : FUNC_MUX
        assign func_state[i] = func_state[i-1] & ~(state[i-1] & in);
    end
    // The output function: a combinational Circut, without any flip-flops.
    // Implement the function o(state) from the state transition diagram.
    // This is a multiplexer chain, with one multiplexer per OUTPUT
    // state (the states used in the OUTPUT, not the register states in the
    // register-transferring diagram).
    wire [1:0] out_func;
    assign out_func[0] = 2'b00;
    genvar j;
    for (j = 1; j < 10; j = j + 1) begin : OUT_MUX
        assign out_func[0] = out_func[0] | (func_state[j] & 2'b00);
        assign out_func[1] = out_func[1] | (func_state[j] & 2'b01);
    end
    assign next_state = func_state;
    assign out1 = out_func[1];
    assign out2 = out_func[0];
endmodule

module TopModule(
    input  in,
    input  [9:0] state,
    output [9:0] next_state,
    output out1,
    output out2
);
    wire [9:0] next_state_combinational;
    assign next_state_combinational[0] = 1'b0;
    assign next_state_combinational[1] = ~in | state[0];
    assign next_state_combinational[2] = ~in & state[1] | in & ~state[0];
    assign next_state_combinational[3] = ~in & state[2] | in & ~state[1];
    assign next_state_combinational[4] = ~in & state[3] | in & ~state[2];
    assign next_state_combinational[5] = ~in & state[4] | in & ~state[3];
    assign next_state_combinational[6] = ~in & state[5] | in & ~state[4];
    assign next_state_combinational[7] = ~in & state[6] | in & ~state[5];
    assign next_state_combinational[8] = ~in & state[7] | in & ~state[6];
    assign next_state_combinational[9] = ~in & state[8] | in & ~state[7];
    assign next_state_combinational[10] = ~in | state[9];
    assign out1 = ~state[1] & state[3] | ~state[2] & ~state[3] & state[4] | ~state[5] & state[2] & state[4] | ~state[6] & ~state[2] & ~state[4] & state[5] | ~state[7] & state[2] & state[3] & state[5] | ~state[8] & ~state[2] & ~state[3] & ~state[4] & ~state[5] & ~state[6] & state[7] | ~state[9] & state[1] & state[2] & state[3] & state[4] & state[5] & state[6] & ~state[7];
    assign out2 = ~state[1] & ~state[3] & ~state[4] & ~state[6] & ~state[7] & ~state[8] & state[9] | state[1] & ~state[2] & ~state[3] & ~state[4] & ~state[5] & ~state[6] & ~state[7] & ~state[8] & state[9] | ~state[1] & state[2] & state[3] & state[4] & ~state[5] & ~state[6] & ~state[7] & ~state[8] & state[9] | ~state[1] & ~state[2] & state[3] & state[4] & state[5] & ~state[6] & ~state[7] & ~state[8] & state[9] | ~state[1] & ~state[2] & ~state[3] & state[4] & state[5] & state[6] & ~state[7] & ~state[8] & state[9];
    assign next_state = next_state_combinational & state;
endmodule

