module TopModule(input in, input [9:0] state, output [9:0] next_state, output out1, output out2);
    reg [9:0] next_state_reg;
    always @(*) begin
        next_state_reg = 10'b0000000000;
        case(state)
            10'b0000000000: begin
                next_state_reg = 10'b0000000001;
                out1 = 1'b0;
                out2 = 1'b0;
            end
            10'b0000000001: begin
                if(in) next_state_reg = 10'b0000000010;
                else next_state_reg = 10'b0000000000;
                out1 = 1'b0;
                out2 = 1'b0;
            end
            10'b0000000010: begin
                next_state_reg = 10'b0000000100;
                out1 = 1'b0;
                out2 = 1'b0;
            end
            10'b0000000100: begin
                if(in) next_state_reg = 10'b0000001000;
                else next_state_reg = 10'b0000000000;
                out1 = 1'b0;
                out2 = 1'b0;
            end
            10'b0000001000: begin
                if(in) next_state_reg = 10'b0000010000;
                else next_state_reg = 10'b0000000000;
                out1 = 1'b0;
                out2 = 1'b0;
            end
            10'b0000010000: begin
                next_state_reg = 10'b0000100000;
                out1 = 1'b0;
                out2 = 1'b0;
            end
            10'b0000100000: begin
                if(in) next_state_reg = 10'b0001000000;
                else next_state_reg = 10'b0000000000;
                out1 = 1'b0;
                out2 = 1'b0;
            end
            10'b0001000000: begin
                next_state_reg = 10'b0010000000;
                out1 = 1'b0;
                out2 = 1'b1;
            end
            10'b0010000000: begin
                next_state_reg = 10'b0100000000;
                out1 = 1'b1;
                out2 = 1'b0;
            end
            10'b0100000000: begin
                next_state_reg = 10'b1000000000;
                out1 = 1'b1;
                out2 = 1'b1;
            end
            default: begin
                next_state_reg = 10'b0000000000;
                out1 = 1'b0;
                out2 = 1'b0;
            end
        endcase
    end
    assign next_state = next_state_reg;
endmodule

module TopModule(
    input  in,
    input  [9:0] state,
    output [9:0] next_state,
    output out1,
    output out2
);
    reg [9:0] next_state_reg;
    always @* begin
        next_state_reg = 10'b0000000000;
        case (state)
            10'b0000000000: if (in) next_state_reg = 10'b0000000001; else next_state_reg = 10'b0000000000;
            10'b0000000001: if (in) next_state_reg = 10'b0000000010; else next_state_reg = 10'b0000000000;
            10'b0000000010: if (in) next_state_reg = 10'b0000000100; else next_state_reg = 10'b0000000000;
            10'b0000000100: if (in) next_state_reg = 10'b0000001000; else next_state_reg = 10'b0000000000;
            10'b0000001000: if (in) next_state_reg = 10'b0000010000; else next_state_reg = 10'b0000000000;
            10'b0000010000: if (in) next_state_reg = 10'b0000100000; else next_state_reg = 10'b0000000000;
            10'b0000100000: if (in) next_state_reg = 10'b0001000000; else next_state_reg = 10'b0000000000;
            10'b0001000000: if (in) next_state_reg = 10'b0010000000; else next_state_reg = 10'b0000000000;
            10'b0010000000: if (in) next_state_reg = 10'b0100000000; else next_state_reg = 10'b0000000000;
            10'b0100000000: if (in) next_state_reg = 10'b1000000000; else next_state_reg = 10'b0000000000;
            10'b1000000000: if (in) next_state_reg = 10'b0000000000; else next_state_reg = 10'b0000000001;
            default: next_state_reg = 10'b0000000000;
        endcase
    end
    assign next_state = next_state_reg;
    assign out1 = (state == 10'b0000000000) ? 1'b0 : 1'b0;
    assign out2 = (state == 10'b0000000000) ? 1'b0 : 1'b0;
    assign out1 = (state == 10'b0000000001) ? 1'b0 : 1'b0;

module TopModule (
    input  in,
    input  [9:0] state,
    output [9:0] next_state,
    output out1,
    output out2
);
    wire in1 = in;
    wire s0 = state[0];
    wire s1 = state[1];
    wire s2 = state[2];
    wire s3 = state[3];
    wire s4 = state[4];
    wire s5 = state[5];
    wire s6 = state[6];
    wire s7 = state[7];
    wire s8 = state[8];
    wire s9 = state[9];
    assign next_state[0] = s1 & in1;
    assign next_state[1] = s2 & ~in1;
    assign next_state[2] = (s3 | s5 | s6 | s9) & in1;
    assign next_state[3] = (s3 | s5 | s6 | s9) & ~in1;
    assign next_state[4] = (s4 | s6 | s7 | s8 | s9) & in1;
    assign next_state[5] = (s4 | s6 | s7 | s8 | s9) & ~in1;
    assign next_state[6] = s0 | (s1 & ~in1);
    assign next_state[7] = s0 | (s1 & in1);
    assign next_state[8] = s0 | (s2 & ~in1);
    assign next_state[9] = s0 | (s2 & in1);
    assign out1 = s7 & ~in1;
    assign out2 = s8 & in1;
endmodule

