module TopModule(input clk, input load, input [255:0] data, output [255:0] q);
    reg [255:0] r0, r1, r2, r3, r4, r5, r6, r7, r8, r9, r10, r11, r12, r13, r14, r15;
    wire [255:0] next0, next1, next2, next3, next4, next5, next6, next7, next8, next9, next10, next11, next12, next13, next14, next15;
    // Next-state logic, combinational (no registers)
    // First row of registers -> row 0 -> row 1 -> etc. -> last row ->
    // first row (toroid). The neighbours of (x,y) are (x+1,y), (x-1,y),
    // (x,y+1), (x,y-1), (x+1,y+1), (x+1,y-1), (x-1,y+1), (x-1,y-1).
    // Neighbour counts are the 8 bits of the 16x16 register at the right
    // position, with 0 neighbours at the left and 8 neighbours at the right.
    // (The 8:0 count is reversed: 0 neighbours are the rightmost bit, 8 are
    // the leftmost.)
    // The middle 8 bits are the current state of the cell (0 -> dead, 1 ->
    // alive), and the outside 8 bits are the next state of the cell (same as
    // the middle 8 bits, but modified by the neighbour counts).
    // The 16 rows of these two 8-bit registers are stitched together to get
    // the 16x16 toroid.
    assign next0 = 8'd0 +: r1 +: r14 +: r15 +: {8{1'b0}};
    assign next1 = 8'd0 +: r0 +: r2 +: r15 +: r16 +: {8{1'b0}};
    assign next2 = 8'd0 +: r1 +: r3 +: r16 +: r17 +: {8{1'b0}};
    assign next3 = 8'd0 +: r2 +: r4 +: r17 +: r18 +: {8{1'b0}};
    assign next4 = 8'd0 +: r3 +: r5 +: r18 +: r19 +: {8{1'b0}};
    assign next5 = 8'd0 +: r4 +: r6 +: r19 +: r20 +: {8{1'b0}};
    assign next6 = 8'd0 +: r5 +: r7 +: r20 +: r21 +: {8{1'b0}};
    assign next7 = 8'd0 +: r6 +: r8 +: r21 +: r22 +: {8{1'b0}};
    assign next8 = 8'd0 +: r7 +: r9 +: r22 +: r23 +: {8{1'b0}};
    assign next9 = 8'd0 +: r8 +: r10 +: r23 +: r24 +: {8{1'b0}};
    assign next10 = 8'd0 +: r9 +: r11 +: r24 +: r25 +: {8{1'b0}};
    assign next11 = 8'd0 +: r10 +: r12 +: r25 +: r26 +: {8{1'b0}};
    assign next12 = 8'd0 +: r11 +: r13 +: r26 +: r27 +: {8{1'b0}};

module Torus16x16 (
    input  wire        clk,
    input  wire        load,
    input  wire [255:0] data,
    output reg  [255:0] q
);
    reg [255:0] next_q;
    integer i, j;
    always @(*) begin
        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                integer neighbours;
                neighbours = q[16*((i-1)%16)+j] + q[16*((i+1)%16)+j] +
                             q[16*i+((j-1)%16)] + q[16*i+((j+1)%16)] +
                             q[16*((i-1)%16)+((j-1)%16)] + q[16*((i-1)%16)+((j+1)%16)] +
                             q[16*((i+1)%16)+((j-1)%16)] + q[16*((i+1)%16)+((j+1)%16)];
                if (q[16*i+j] && neighbours < 2) next_q[16*i+j] = 1'b0;
                else if (q[16*i+j] && neighbours < 4) next_q[16*i+j] = 1'b1;
                else if (q[16*i+j] && neighbours >= 4) next_q[16*i+j] = 1'b0;
                else if (!q[16*i+j] && neighbours == 3) next_q[16*i+j] = 1'b1;
                else next_q[16*i+j] = q[16*i+j];
            end
        end
    end
    always @(posedge clk) begin
        if (load) q <= 256'h0;
        else q <= next_q;
    end
endmodule

module TopModule(input clk, input load, input [255:0] data, output [255:0] q);
  reg [255:0] next_q;
