module TopModule(input clk, input load, input [255:0] data, output [255:0] q);
    reg [255:0] r_reg, r_next;

    always @* begin
        // This array calculates the number of neighbouring cells for
        // each (x, y) pair. If (x, y) is a corner cell, it wraps around
        // to the opposite side of the grid.
        integer neighbours[(0:15)->(0:15)];
        integer x, y;
        for (x = 0; x < 16; x = x + 1) begin
            for (y = 0; y < 16; y = y + 1) begin
                neighbours[x][y] = r_reg[16*((y - 1 + 16) % 16) + 16*16*((x - 1 + 16) % 16)] +
                                   r_reg[16*((y - 1 + 16) % 16) + 16*16*x] +
                                   r_reg[16*((y - 1 + 16) % 16) + 16*16*((x + 1) % 16)] +
                                   r_reg[16*y + 16*16*((x - 1 + 16) % 16)] +
                                   r_reg[16*y + 16*16*((x + 1) % 16)] +
                                   r_reg[16*((y + 1) % 16) + 16*16*((x - 1 + 16) % 16)] +
                                   r_reg[16*((y + 1) % 16) + 16*16*x] +
                                   r_reg[16*((y + 1) % 16) + 16*16*((x + 1) % 16)];
            end
        end

        // This array calculates the next state of the game for each
        // (x, y) pair.
        integer next_r[(0:15)->(0:15)];
        for (x = 0; x < 16; x = x + 1) begin
            for (y = 0; y < 16; y = y + 1) begin
                if (neighbours[x][y] < 2)
                    next_r[x][y] = 0;
                else if (neighbours[x][y] == 2)
                    next_r[x][y] = r_reg[16*y + x];
                else if (neighbours[x][y] == 3)
                    next_r[x][y] = 1;
                else
                    next_r[x][y] = 0;
            end
        end

        // Register the next state of the game.
        r_next = 0;
        for (x = 0; x < 16; x = x + 1) begin
            for (y = 0; y < 16; y = y + 1) begin
                r_next[16*y + x] = next_r[x][y];
            end
        end
    end

    // Synchronous load: transition to new data on the next clock
    // edge.
    always @(posedge clk) begin
        if (load)
            r_reg <= 256'd0;
        else
            r_reg <= r_next;
    end

    // Output the current register state.
    assign q = r_reg;
endmodule

module TopModule(clk, load, data, q);
  input clk;
  input load;
  input [255:0] data;
  output [255:0] q;
  reg [255:0] q;
  reg [255:0] next_q;
  integer i;
  integer j;
  integer k;
  integer neighbours;
  always @(posedge clk) begin
    if (load) begin
      q <= data;
    end else begin
      for (i = 0; i < 16; i = i + 1) begin
        for (j = 0; j < 16; j = j + 1) begin
          neighbours = 0;
          for (k = 0; k < 9; k = k + 1) begin
            neighbours = neighbours + q[(((i + k/3 - 1) % 16) * 16 + ((j + k%3 - 1) % 16))];
          end
          if (neighbours == 3) begin
            next_q[i * 16 + j] = 1;
          end else if (neighbours == 4) begin
            next_q[i * 16 + j] = q[i * 16 + j];
          end else if (neighbours < 3) begin
            next_q[i * 16 + j] = 0;
          end else begin
            next_q[i * 16 + j] = 0;
          end
        end
      end
      q <= next_q;
    end
  end
endmodule

