// One-bit FSM state encoding: 00 = idle, 01 = start bit, 10 = receive bits,
// 11 = stop bit.
reg [1:0] state;
reg [7:0] data;
reg [2:0] bit_count;
reg done;
always @(posedge clk) begin
    if (reset) begin
        state <= 2'b00;
        data <= 8'b0;
        bit_count <= 3'b000;
        done <= 1'b0;
    end else begin
        case (state)
            2'b00: begin // idle, wait for start bit
                if (in == 1'b0) begin
                    state <= 2'b01;
                    bit_count <= 3'b000;
                end
            end
            2'b01: begin // start bit, wait for 8 data bits
                if (bit_count == 3'b011) begin
                    state <= 2'b10;
                    bit_count <= 3'b000;
                end else begin
                    bit_count <= bit_count + 1;
                end
            end
            2'b10: begin // receive bits, wait for stop bit
                data <= {in, data[7:1]};
                if (bit_count == 3'b011) begin
                    state <= 2'b11;
                    bit_count <= 3'b000;
                end else begin
                    bit_count <= bit_count + 1;
                end
            end
            2'b11: begin // stop bit, send data and go back to idle
                if (in == 1'b1) begin
                    done <= 1'b1;
                    state <= 2'b00;
                end
            end
        endcase
    end
end
// Output is registered, so it will go high one clock cycle after the stop
// bit, and stay high for the rest of the frame.
