// A separate always block for the state table, as described in lectures.
// The state table is a lookup table that defines the next state as a
// function of the current state and the input signals.
always @(*) begin
    case ({r[0], r[1], r[2], state})
        3'b0000: next_state = 3'b000;
        3'b0001: next_state = 3'b001;
        3'b0010: next_state = 3'b010;
        3'b0011: next_state = 3'b011;
        3'b0100: next_state = 3'b000;
        3'b0101: next_state = 3'b010;
        3'b0110: next_state = 3'b001;
        3'b0111: next_state = 3'b011;
        3'b1000: next_state = 3'b000;
        3'b1001: next_state = 3'b010;
        3'b1010: next_state = 3'b001;
        3'b1011: next_state = 3'b011;
        3'b1100: next_state = 3'b000;
        3'b1101: next_state = 3'b010;
        3'b1110: next_state = 3'b001;
        3'b1111: next_state = 3'b011;
    endcase
end

// A separate always block for the state flip-flops, as described in
// lectures. Each flip-flop is a register that stores the current state,
// and is updated on the positive edge of the clock.
always @(posedge clk) begin
    if (!resetn) begin
        state <= 3'b000;
    end else begin
        state <= next_state;
    end
end

// The outputs, g[i], are functions of the current state. We can describe
// them using a continuous assignment statement, that sets the value of the
// output register to 1 when the state is the appropriate value, and to 0
// otherwise.
assign g[0] = (state == 3'b000) || (state == 3'b001) || (state == 3'b010) || (state == 3'b011);
assign g[1] = (state == 3'b001) || (state == 3'b011);
assign g[2] = (state == 3'b000) || (state == 3'b010) || (state == 3'b011);

// The FSM is a priority arbiter, meaning that it gives a grant to the
// highest-priority requesting device. The priority is as described in
// the FSM description.
//
// Since we're using separate always blocks for the state table and the
// state flip-flops, the FSM is synchronous, and the register update
// happens on the positive edge of the clock. This gives us a nice clean
// synchronous FSM, without any combinational loops.
endmodule

