                delay = 16'd0;
            end
            default: delay = 16'd0;
        endcase
    end
endmodule

module Timer (
  input clk,
  input reset,
  input data,
  output reg [3:0] count,
  output reg counting,
  output reg done,
  input ack
);
  reg [3:0] delay;
  reg [15:0] counter;
  reg [1:0] state;
  parameter IDLE = 2'd0, COUNTING = 2'd1, DONE = 2'd2;
  always @(posedge clk) begin
    if (reset) begin
      count <= 4'd0;
      delay <= 4'd0;
      counter <= 16'd0;
      state <= IDLE;
      counting <= 1'b0;
      done <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (data & ~delay[0] & delay[1] & ~delay[2] & delay[3]) begin
            state <= COUNTING;
            counting <= 1'b1;
            counter <= 16'd0;
          end
          delay <= {data, delay[3:1]};
        end
        COUNTING: begin
          counter <= counter + 16'd1;
          if (counter == 16'd999) begin
            count <= 4'd9;
          end else if (counter == 16'd1999) begin
            count <= 4'd8;
          end else if (counter == 16'd2999) begin
            count <= 4'd7;
          end else if (counter == 16'd3999) begin
            count <= 4'd6;
          end else if (counter == 16'd4999) begin
            count <= 4'd5;
          end else if (counter == 16'd5999) begin
            count <= 4'd4;
          end else if (counter == 16'd6999) begin
            count <= 4'd3;
          end else if (counter == 16'd7999) begin
            count <= 4'd2;
          end else if (counter == 16'd8999) begin
            count <= 4'd1;
          end else if (counter == 16'd9999) begin
            count <= 4'd0;
            state <= DONE;
            counting <= 1'b0;
          end
        end
        DONE: begin
          done <= 1'b1;
          if (ack) begin
            state <= IDLE;
            delay <= 4'd0;
            done <= 1'b0;
          end
        end
      endcase
    end
  end
endmodule

module TopModule(
    input clk,
    input reset,
    input data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input ack
);
    reg [3:0] delay;
    reg [15:0] counter;
    reg [1:0] state;
    parameter IDLE = 2'd0, COUNTING = 2'd1, DONE = 2'd2;

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'd0;
            counting <= 1'b0;
            done <= 1'b0;
            delay <= 4'd0;
            counter <= 16'd0;
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (data & ~delay[0]) begin
                        delay <= 4'd1;
                    end else if (data & delay[0] & ~delay[1]) begin
                        delay <= 4'd2;
                    end else if (data & delay[1] & ~delay[2]) begin
                        delay <= 4'd3;
                    end else if (data & delay[2] & ~delay[3]) begin
                        delay <= 4'd4;
                    end else if (data & delay[3]) begin
                        counting <= 1'b1;
                        counter <= 16'd0;
                        state <= COUNTING;
                    end
                end
                COUNTING: begin
                    counter <= counter + 16'd1;
                    if (counter == (delay * 16'd1000) - 16'd1) begin
                        counting <= 1'b0;
                        done <= 1'b1;
                        state <= DONE;
                    end else begin
                        count <= 4'd10 - ((counter + 16'd1) / 16'd1000);
                    end
                end
                DONE: begin
                    if (ack) begin
                        done <= 1'b0;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
endmodule

module one_shot(
    input clk,
    input reset,
    input pulse,
    output reg pulse_p1
);
    reg sr;
    always @(posedge clk) begin
        if (reset) begin
            sr <= 1'b0;
            pulse_p1 <= 1'b0;
        end else begin
            sr <= sr ? ~sr & pulse : pulse;
            pulse_p1 <= sr;
        end
    end
endmodule

module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [15:0] counter;
    reg [1:0] state;
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'd0;
            delay <= 4'd0;
            counter <= 16'd0;
            state <= 2'd0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            case (state)
                2'd0: begin // search for start sequence
                    if (data & ~counter[15]) begin
                        counter <= counter + 1;
                        if (counter == 16'd1100) begin
                            counter <= 16'd0;
                            state <= 2'd1;
                        end
                    end else begin
                        counter <= 16'd0;
                    end
                end
                2'd1: begin // shift in delay bits
                    delay <= {delay[2:0], data};
                    counter <= counter + 1;
                    if (counter == 16'd1200) begin
                        counter <= 16'd0;
                        state <= 2'd2;
                    end
                end
                2'd2: begin // start counting
                    counting <= 1'b1;
                    counter <= 16'd0;
                    state <= 2'd3;
                end
                2'd3: begin // counting
                    count <= delay;
                    counter <= counter + 1;
                    if (counter == (delay + 1) * 1000) begin
                        counting <= 1'b0;
                        done <= 1'b1;
                        state <= 2'd4;
                    end else begin
                        count <= delay - counter[15:12];
                    end
                end
                2'd4: begin // wait for ack
                    if (ack) begin
                        state <= 2'd0;
                        done <= 1'b0;
                    end
                end
            endcase
        end
    end
endmodule

module TopModule(
    input  wire        clk,
    input  wire        reset,
    input  wire        data,
    output wire [3:0]  count,
    output wire        counting,
    output wire        done,
    input  wire        ack
);
    reg [3:0] delay;
    reg [11:0] countdown;
    reg [1:0] state;
    reg trigger;
    always @(posedge clk) begin
        if (reset) begin
            delay <= 4'd0;
            countdown <= 12'd0;
            state <= 2'd0;
            trigger <= 1'b0;
        end else begin
            case (state)
                2'd0: begin // search for 1101
                    if (data && !trigger) begin
                        trigger <= 1'b1;
                    end else if (!data && trigger) begin
                        trigger <= 1'b0;
                    end
                    if (trigger && data && !countdown) begin
                        delay <= data ? 4'd1 : delay << 1 | data;
                        countdown <= 12'd999;
                        state <= 2'd1;
                    end
                end
                2'd1: begin // counting down, assert counting output
                    countdown <= countdown - 1'b1;
                    if (!countdown) begin
                        state <= 2'd2;
                    end
                end
                2'd2: begin // delay one extra clock cycle, assert done
                    state <= 2'd3;
                end
                2'd3: begin // wait for ack, go back to the start
                    if (ack) begin
                        state <= 2'd0;
                    end
                end
            endcase
        end
    end
    assign count = state == 2'd1 ? countdown[11:8] : 4'd0;
    assign counting = state == 2'd1;
    assign done = state == 2'd2;
endmodule

module TopModule(
  input clk,
  input reset,
  input data,
  output reg [3:0] count,
  output reg counting,
  output reg done,
  input ack
);
  reg [2:0] state;
  reg [3:0] delay;
  reg [15:0] counter;
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'd0;
      delay <= 4'd0;
      counter <= 16'd0;
      count <= 4'd0;
      counting <= 1'b0;
      done <= 1'b0;
    end else begin
      case (state)
        3'd0: begin // idle
          if (data && !delay) begin
            state <= 3'd1;
            counter <= 16'd1;
            delay <= 4'd0;
          end
        end
        3'd1: begin // shift in delay bits 0-3
          delay <= {data, delay[3:1]};
          counter <= 16'd1;
          state <= 3'd2;
        end
        3'd2: begin // delay 1 clock cycle
          counter <= counter + 16'd1;
          state <= 3'd3;
        end
        3'd3: begin // count up to delay + 1
          counter <= counter + 16'd1;
          count <= counter[3:0];
          if (counter == delay) begin
            counting <= 1'b1;
            state <= 3'd4;
          end
        end
        3'd4: begin // wait for counting to go low
          if (!counting) begin
            done <= 1'b1;
            state <= 3'd5;
          end
        end
        3'd5: begin // wait for ack
          if (ack) begin
            done <= 1'b0;
            counter <= 16'd0;
            delay <= 4'd0;
            count <= 4'd0;
            counting <= 1'b0;
            state <= 3'd0;
          end
        end
      endcase
    end
  end
endmodule

module TopModule(
    input clk,
    input reset,
    input data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input ack);

    reg [3:0] delay;
    reg [15:0] counter;
    reg [1:0] state;

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0;
            delay <= 4'b0;
            counter <= 16'b0;
            state <= 2'b00;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            case (state)
                2'b00: begin // search for the start sequence
                    if (data && !delay) begin
                        state <= 2'b01;
                        counter <= 16'b1;
                    end
                end
                2'b01: begin // shift in the delay bits
                    delay <= {delay[2:0], data};
                    if (counter == 16'b1000) begin
                        state <= 2'b10;
                        counter <= 16'b0;
                    end else begin
                        counter <= counter + 1'b1;
                    end
                end
                2'b10: begin // count
                    count <= counter[3:0];
                    if (counter == 16'b1111) begin
                        state <= 2'b00;
                        counting <= 1'b0;
                        done <= 1'b1;
                    end else begin
                        counter <= counter + 1'b1;
                    end
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            counting <= 1'b0;
        end else if (state == 2'b10 && counter == 16'b0) begin
            counting <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            done <= 1'b0;
        end else if (state == 2'b00 && ack) begin
            done <= 1'b0;
        end
    end
endmodule

// One-bit register: the inline command "reg" declares a register, which is
// a flip-flop without an enable input. The register is initialized to 1'b0
// on reset.
reg [3:0] count = 4'd0;
reg counting = 1'b0;
reg done = 1'b0;
reg [2:0] delay = 3'd0;
reg [2:0] delay_counter = 3'd0;
reg [10:0] count_remaining = 11'd0;
reg [1:0] state = 2'd0;

always @(posedge clk) begin
    if (reset) begin
        count <= 4'd0;
        counting <= 1'b0;
        done <= 1'b0;
        delay <= 3'd0;
        delay_counter <= 3'd0;
        count_remaining <= 11'd0;
        state <= 2'd0;
    end else begin
        case (state)
            2'd0: begin // Search for the start pattern
                if (data && !count[3] && !count[2] && count[1] && count[0]) begin
                    state <= 2'd1;
                end else begin
                    count <= count + 1'b1;
                end
            end
            2'd1: begin // Shift in the next 4 bits to determine the delay
                if (!count[3] && !count[2] && !count[1] && !count[0]) begin
                    delay <= data ? 3'd7 : 3'd6;
                    state <= 2'd2;
                end else begin
                    count <= count + 1'b1;
                end
            end
            2'd2: begin // Start counting
                counting <= 1'b1;
                count_remaining <= (delay + 1'b1) * 11'd1000;
                state <= 2'd3;
            end
            2'd3: begin // Wait for the counters to finish counting
                if (count_remaining == 11'd0) begin
                    counting <= 1'b0;
                    done <= 1'b1;
                    state <= 2'd4;
                end else begin
                    count_remaining <= count_remaining - 11'd1000;
                end
            end
            2'd4: begin // Wait for the user to acknowledge the timer
                if (ack) begin
                    delay <= 3'd0;
                    state <= 2'd0;
                end
            end
        endcase
    end
end

// The count output is only known when the state machine is not counting.
// In the counting state, the count output is don't-care, as the state
// machine doesn't update it.
assign count = (state == 2'd3) ? 4'd0 : count;

endmodule

module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [1:0] state;
    reg [3:0] delay;
    reg [12:0] counter;
    reg [12:0] target;
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'd0;
            delay <= 4'd0;
            counter <= 13'd0;
            target <= 13'd0;
            count <= 4'd0;
            counting <= 1'd0;
            done <= 1'd0;
        end else begin
            case (state)
                2'd0: begin // search for the start sequence
                    if (data && delay == 4'd11) begin
                        state <= 2'd1;
                        delay <= 4'd0;
                        counter <= 13'd0;
                        target <= 13'd1000;
                    end else begin
                        delay <= delay + 1;
                    end
                end
                2'd1: begin // shift in the next 4 bits
                    delay <= {delay[2:0], data};
                    if (delay == 4'd11) begin
                        state <= 2'd2;
                        counter <= 13'd0;
                        target <= {1'd0, delay} * 1000;
                    end
                end
                2'd2: begin // count for exactly target cycles
                    counter <= counter + 1;
                    if (counter == target) begin
                        state <= 2'd3;
                        counting <= 1'd0;
                        done <= 1'd1;
                        count <= delay;
                    end else begin
                        counting <= 1'd1;
                        count <= delay - counter / 1000;
                    end
                end
                2'd3: begin // wait for ack to go high
                    if (ack) begin
                        state <= 2'd0;
                        delay <= 4'd0;
                        counter <= 13'd0;
                        target <= 13'd0;
                        count <= 4'd0;
                        counting <= 1'd0;
                        done <= 1'd0;
                    end
                end
            endcase
        end
    end
endmodule
